<?php declare(strict_types=1); ?>
<div class="page-wrap financial-report"><a href="<?= pl_e(pl_url('/reports')) ?>" class="back-link"><?= pl_icon('arrow-left') ?> All reports</a><div class="page-heading"><div><p class="eyebrow">What you own. What you owe.</p><h1>Balance sheet</h1><p class="muted"><?= pl_e($company['name']) ?> · As of <?= pl_e(pl_date_label($asOf)) ?></p></div><form method="get" action="<?= pl_e(pl_url('/reports/balance-sheet')) ?>" class="report-filter"><label class="field">As of date<input type="date" name="as_of" value="<?= pl_e($asOf) ?>" required></label><button class="button secondary">Update</button></form></div>
<div class="report-kpis"><div><span>Total assets</span><strong><?= pl_e($company['currency'] . ' ' . pl_money($report['total_assets'])) ?></strong></div><div><span>Total liabilities</span><strong><?= pl_e($company['currency'] . ' ' . pl_money($report['total_liabilities'])) ?></strong></div><div><span>Equity including earned profit</span><strong><?= pl_e($company['currency'] . ' ' . pl_money($report['total_equity'])) ?></strong></div></div>
<div class="statement-columns"><?php foreach (['assets' => 'Assets', 'liabilities' => 'Liabilities', 'equity' => 'Equity'] as $key => $label): ?><section class="panel"><h2><?= pl_e($label) ?></h2><div class="table-wrap"><table class="data-table statement-table"><caption class="sr-only"><?= pl_e($label . ' in ' . $company['currency']) ?></caption><tbody><?php foreach ($report[$key] as $row): ?><tr><th scope="row"><a href="<?= pl_e(pl_url('/reports/account', ['id' => $row['id'], 'as_of' => $asOf])) ?>"><span class="account-code"><?= pl_e($row['code']) ?></span><?= pl_e($row['name']) ?></a></th><td class="amount"><?= pl_e(pl_money($row['amount'])) ?></td></tr><?php endforeach; ?><?php if ($key === 'equity'): ?><tr><th scope="row">Earned profit to date <span class="row-secondary muted">Unclosed income less expenses</span></th><td class="amount"><?= pl_e(pl_money($report['earned_profit'])) ?></td></tr><?php endif; ?></tbody><tfoot><tr><th scope="row">Total <?= pl_e(strtolower($label)) ?></th><td class="amount"><?= pl_e(pl_money($report['total_' . $key])) ?></td></tr></tfoot></table></div></section><?php endforeach; ?></div>
<div class="report-reconciliation"><strong><?= $report['balanced'] ? 'Assets = liabilities + equity' : 'This statement needs review' ?></strong><span><?= pl_e(pl_money($report['total_assets'])) ?> = <?= pl_e(pl_money($report['total_liabilities_equity'])) ?> <?= pl_e($company['currency']) ?></span></div><p class="small muted">Posted entries only. Earned profit is shown separately from recorded equity. Account classification and completeness still need review; balanced totals alone do not establish correct books.</p></div>
